-- Study Abroad country content, BATCH 24: English-speaking Caribbean (Bahamas, Barbados, Belize, Antigua, Dominica, Grenada, St Kitts, St Lucia, SVG).
-- Researched from public sources in November 2026 (see backend/TODO_country_tables.md for what still needs checking).
-- Text blocks fill the columns on countries; subject / course rows are linked to subjects / specializations
-- (country_sections.subject_id / specialization_id) so the website links them to those pages.
-- Replaces the earlier '[Sample]' / '[Placeholder]' rows of these 5 countries. Safe to re-run.
-- Requires alembic revision e6a3c9d1f4b7 (alembic upgrade head).
BEGIN;
DELETE FROM country_sections WHERE country_id IN (SELECT id FROM countries WHERE slug IN ('bahamas', 'barbados', 'belize', 'antigua-and-barbuda', 'dominica', 'grenada', 'saint-kitts-and-nevis', 'saint-lucia', 'saint-vincent-and-the-grenadines'));
UPDATE countries SET why_title = 'Why study in the Bahamas?', why_body = '<p>The Bahamas offers English-medium degrees at the University of The Bahamas in a tourism-driven island nation close to the United States.<ul><li>English-medium teaching</li><li>Strengths in tourism, hospitality, marine science and business</li><li>Close to the US</li><li>Small campuses</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Every non-Bahamian student needs a <strong>Permit to Reside</strong> approved before arrival, and some nationalities also need an entry visa. UB lists evidence of permission to study from the Department of Immigration as an admission requirement.</p><ul><li>Admission letter from the University of The Bahamas</li><li>Permit to Reside approved before arrival</li><li>Entry visa depending on nationality</li><li>Sufficient funds for tuition and living costs</li><li>Employment opportunities for students are restricted</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Bahamas Department of Immigration and the University of The Bahamas site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each institution.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof for non-native speakers</li><li>Entrance requirements per programme (medicine: science prerequisites, often MCAT)</li><li>Medical certificate and health insurance</li><li>Passport copy, photographs and application fee</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>International tuition is charged per contact hour.</p><ul><li>UB international rate: B$230 per contact hour for undergraduate courses for students admitted from Fall 2019 (secondary guide), plus fees, VAT and books</li><li>The government tertiary grant is for Bahamian citizens only</li><li>Living costs: about US$1,200-$2,000 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'bahamas';
UPDATE countries SET why_title = 'Why study in Barbados?', why_body = '<p>Barbados is home to The UWI Cave Hill campus and Ross University School of Medicine, in an English-speaking Caribbean island with a long academic tradition.<ul><li>English-medium teaching</li><li>UWI Cave Hill campus</li><li>Ross University School of Medicine</li><li>Strengths in law, medicine, tourism and business</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Non-Barbadian students must hold a <strong>student visa</strong> throughout their study. The application starts through the university before arrival; Cave Hill''s deadline for visa documents was 30 September 2026, so late applicants should contact the admissions office.</p><ul><li>Birth certificate copy, passport bio page, photos and the visa fee (reported at BBD 300; unconfirmed)</li><li>International students may not work except limited hours on campus</li><li>A separate work permit is needed for any other work</li><li>Students are registered in the campus student care health plan</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official The UWI Cave Hill admissions office and Barbados immigration site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to the university; Cave Hill handles visa processing.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof for non-native speakers</li><li>Entrance requirements per programme (medicine: science prerequisites, often MCAT)</li><li>Medical certificate and health insurance</li><li>Passport copy, photographs and application fee</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition figures below are for 2025-26; 2026-27 fees were not yet published in the guide used.</p><ul><li>Most humanities, science and social science bachelor''s: about US$18,650 a year for international students</li><li>LLB Law: about US$27,000 a year</li><li>Mandatory university fees apply on top</li><li>Living costs: about US$1,000-$1,800 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate (CSEC/CAPE or equivalent)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'barbados';
UPDATE countries SET why_title = 'Why study in Belize?', why_body = '<p>Belize is an English-speaking Central American country with the University of Belize and a medical school, in a tourism and conservation-focused economy.<ul><li>English-medium teaching</li><li>Rich biodiversity and marine environment</li><li>Strengths in environment, tourism and health</li><li>Small, friendly campuses</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>A valid <strong>student permit</strong> must be obtained before each semester; the permit covers one semester. Working needs a separate Temporary Employment Permit from the Labour Department.</p><ul><li>Admission letter from a Belizean institution</li><li>Permit fee sources conflict: BZ$200 for most nationalities, BZ$750 for some South Asian and other nationals, BZ$3,000 for China (Studycountry, in effect since 1 May 2020)</li><li>Check the Immigration Department fee table before budgeting</li><li>Apply early; visa processing times vary</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Belize Immigration Department and the University of Belize site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each institution.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof for non-native speakers</li><li>Entrance requirements per programme (medicine: science prerequisites, often MCAT)</li><li>Medical certificate and health insurance</li><li>Passport copy, photographs and application fee</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No general undergraduate international tuition schedule was found.</p><ul><li>University of Belize School of Medicine: US$29,600 a year tuition for international students in 2026; about US$38,700 with fees, insurance and books</li><li>Student permits are paid separately and are not covered by scholarships</li><li>Living costs: about US$600-$1,000 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'belize';
UPDATE countries SET why_title = 'Why study in Antigua and Barbuda?', why_body = '<p>Antigua and Barbuda hosts the UWI Five Islands campus and several US-style medical schools in an English-speaking Caribbean island nation.<ul><li>English-medium teaching</li><li>UWI Five Islands campus</li><li>Medical schools such as the American University of Antigua</li><li>Tourism and hospitality strengths</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Non-OECS students generally need a <strong>student permit</strong> from the Immigration Department, and some nationalities also need an entry visa. Holders of certain US, UK, Canadian or Schengen visas can get a visa on arrival for US$100 (UWI Five Islands).</p><ul><li>Admission letter from a recognised institution</li><li>Student permit from the Immigration Department</li><li>Visa on arrival costs US$100 for eligible nationalities</li><li>One law-firm source says a US proclamation restricts new US student visas for Antigua and Barbuda nationals from 1 January 2026; confirm with the US government</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Antigua and Barbuda Immigration Department and your institution site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each institution.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof for non-native speakers</li><li>Entrance requirements per programme (medicine: science prerequisites, often MCAT)</li><li>Medical certificate and health insurance</li><li>Passport copy, photographs and application fee</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Only UWI Five Islands fees were found.</p><ul><li>UWI Five Islands bachelor''s programmes: US$10,000-$12,000 per academic year (2024/25 schedule)</li><li>Medical school tuition: not confirmed; check each school</li><li>Living costs: about US$900-$1,600 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'antigua-and-barbuda';
UPDATE countries SET why_title = 'Why study in Dominica?', why_body = '<p>Dominica is a small English-speaking Caribbean island with a medical school and a state college, known for its natural environment.<ul><li>English-medium teaching</li><li>All Saints University School of Medicine</li><li>Dominica State College</li><li>Eco-tourism and environment strengths</li></ul></p><p>Ross University School of Medicine moved from Dominica to Barbados, so check the school''s current location before applying.</p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Dominica does not appear to publish one exhaustive student-visa rulebook. Citizens of Commonwealth, CARICOM, US and several EU countries can enter visa-free for up to six months; other nationalities apply for a visa, and all travellers submit an online ED card within three days of arrival.</p><ul><li>Acceptance letter from an approved institution</li><li>Student permission described for approved institutions, including medical programmes</li><li>Medical examination may be required</li><li>Check the Ministry of National Security and your institution</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Government of Dominica and your institution site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each institution.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof for non-native speakers</li><li>Entrance requirements per programme (medicine: science prerequisites, often MCAT)</li><li>Medical certificate and health insurance</li><li>Passport copy, photographs and application fee</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Fee levels vary by institution.</p><ul><li>All Saints University: about US$92,250 (4-year MD) and US$108,330 (5-year MD) before living costs (checked October 2026)</li><li>Living costs: about US$900-$1,500 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'dominica';
UPDATE countries SET why_title = 'Why study in Grenada?', why_body = '<p>Grenada is home to St. George''s University, a large international medical, veterinary and arts and sciences school in an English-speaking Caribbean island.<ul><li>English-medium teaching</li><li>St. George''s University</li><li>Medicine, veterinary medicine and sciences</li><li>Students from many countries</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Accepted SGU students are not required to carry a visa when travelling to Grenada; they carry a valid passport and their SGU acceptance letter. Visa-required nationalities are processed on arrival, and students from visa-exempt countries can extend their stay up to one year at the Immigration Office.</p><ul><li>Valid passport and SGU acceptance letter</li><li>Visa-required students are processed on arrival</li><li>Stays can be extended up to one year at the main Immigration Office in St. George''s</li><li>Work is generally not allowed unless separately authorised</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official SGU and the Grenada immigration authorities site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to SGU or the other institutions.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof for non-native speakers</li><li>Entrance requirements per programme (medicine: science prerequisites, often MCAT)</li><li>Medical certificate and health insurance</li><li>Passport copy, photographs and application fee</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>SGU''s official tuition pages list rates effective 1 June 2026 in US dollars.</p><ul><li>School of Medicine: about US$34,100-$37,700 per term (blog connected to SGU)</li><li>Confirm the tables on the SGU tuition pages</li><li>Do not confuse SGU with St George''s, University of London</li><li>Living costs: about US$1,000-$1,800 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'grenada';
UPDATE countries SET why_title = 'Why study in Saint Kitts and Nevis?', why_body = '<p>Saint Kitts and Nevis hosts several offshore medical and veterinary schools in an English-speaking twin-island nation.<ul><li>English-medium teaching</li><li>Ross University School of Veterinary Medicine</li><li>University of Medicine and Health Sciences, Medical University of the Americas</li><li>Small, safe islands</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>International students at recognised institutions can apply for a <strong>student visa</strong> for the duration of their programme. No single consolidated official student-visa page was found. From 2026 all air travellers complete an eTA and Electronic Travel Declaration before boarding.</p><ul><li>Student visa before arrival</li><li>Proof of acceptance at a recognised institution</li><li>Evidence of financial resources and mandatory health insurance</li><li>Complete the eTA and travel declaration before flying</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Ministry of Homeland Security and your institution site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each institution.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof for non-native speakers</li><li>Entrance requirements per programme (medicine: science prerequisites, often MCAT)</li><li>Medical certificate and health insurance</li><li>Passport copy, photographs and application fee</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No official tuition figures were found.</p><ul><li>Contact each medical school for tuition</li><li>Living costs: about US$900-$1,600 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'saint-kitts-and-nevis';
UPDATE countries SET why_title = 'Why study in Saint Lucia?', why_body = '<p>Saint Lucia has an English-medium Sir Arthur Lewis Community College, a US university campus and a medical school in a Caribbean island nation.<ul><li>English-medium teaching</li><li>Spartan Health Sciences University</li><li>Sir Arthur Lewis Community College</li><li>Tourism and hospitality strengths</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Requirements depend on nationality. Once accepted, students apply for a <strong>student visa</strong> at the nearest Saint Lucian embassy or consulate (secondary guides); no 2026 fees or processing times were found.</p><ul><li>Acceptance letter from the institution</li><li>Visa and study authorisation depending on nationality</li><li>Spartan listings name a motivation letter, IELTS/TOEFL, medical certificate, insurance and proof of funds</li><li>Confirm with Saint Lucia immigration</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Saint Lucia immigration and your institution site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each institution.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof for non-native speakers</li><li>Entrance requirements per programme (medicine: science prerequisites, often MCAT)</li><li>Medical certificate and health insurance</li><li>Passport copy, photographs and application fee</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Figures conflict across sources.</p><ul><li>Spartan Health Sciences University: about US$12,500 a year (listing)</li><li>Private universities: XCD 10,000-30,000 a year (guide; about US$3,700-$11,100)</li><li>Monroe University St. Lucia publishes a 2026-27 fee schedule</li><li>Living costs: about US$800-$1,400 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'saint-lucia';
UPDATE countries SET why_title = 'Why study in Saint Vincent and the Grenadines?', why_body = '<p>Saint Vincent and the Grenadines has a medical school, a community college and UWI Open Campus services in an English-speaking Caribbean nation.<ul><li>English-medium teaching</li><li>St. James School of Medicine</li><li>Saint Vincent and the Grenadines Community College</li><li>Small, safe islands</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>The country runs a nationality-based visa system. Once accepted, students apply for a <strong>student visa</strong> at the nearest Saint Vincent and the Grenadines embassy or consulate.</p><ul><li>Acceptance letter from the institution</li><li>Processing can take up to three months in the Caribbean (general guide)</li><li>Working without a work permit is illegal</li><li>Confirm with immigration and the institution</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official SVG immigration and your institution site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each institution.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof for non-native speakers</li><li>Entrance requirements per programme (medicine: science prerequisites, often MCAT)</li><li>Medical certificate and health insurance</li><li>Passport copy, photographs and application fee</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition varies by institution.</p><ul><li>2026 guide: public universities average US$2,000-$6,000 a year (may not apply to private medical schools)</li><li>Check each school''s fee schedule</li><li>Living costs: about US$800-$1,400 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'saint-vincent-and-the-grenadines';
COMMIT;
